frame.store("respond", { let __signature_1414 = Signature { name: "respond".into(), positional: vec!["text".into(),"memory".into()], positional_only: 0, defaults: vec![], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_1416 = Value::dict(); __attrs_1416.dict_set(Value::from("__doc__"), Value::from("The store's reply, with the names in it written as the store holds them.\n\n    A plan is quoted back in the words they typed, so a name in it came back in their spelling:\n    \"we r going 2 spain in may\" -> \"You r going 2 spain in may.\". Every route out of the store\n    ends here, so the names are written once, at the end.\n\n    Then the floor under it: never the same words twice in a row. The store answers each line on\n    its own terms, so two different lines can be answered by the same words - \"is she vegan\" and\n    then \"what does my mum eat\" both reached the one line the store writes about a diet nobody\n    gave, and the person read the same sentence twice. Whatever route the reply came by,\n    `bot/memory/again.instead` frames it as the repeat it is - after the names are written, so\n    the words it compares are the words on the screen.\n    "))?; __attrs_1416.dict_set(Value::from("__defaults__"), Value::None)?; let __kwdefaults_1417 = Value::dict(); __attrs_1416.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_1413 = Frame::module(frame.globals.clone()); let mut __function_1415 = NativeFunction::qualified_with_origin("respond".into(), "respond".into(), "bot.modules.memory_store".into(), __attrs_1416, pyrt::object::FunctionOrigin { span: pyrt::runtime::SourceSpan { file: "bot/modules/memory_store.py", first: 4191, last: 4358, qualname: "respond" }, closure: __closure_1413.clone(), freevars: vec![] }, move |rt, args| __py_79::respond(rt, __closure_1413.clone(), &__signature_1414, args)); __function_1415 })?;
frame.store("_asks_to_hear_it_again", { let __signature_1419 = Signature { name: "_asks_to_hear_it_again".into(), positional: vec!["text".into(),"memory".into()], positional_only: 0, defaults: vec![], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_1421 = Value::dict(); __attrs_1421.dict_set(Value::from("__doc__"), Value::from("True for the one turn where the same words are the answer: \"what did you say earlier\".\n\n    STYLE.md's rule is about answering twice, not about being asked twice: a person who asks to\n    hear the last answer again is handed it, and framing that as \"Same answer, and it covers\n    this:\" says the words were volunteered again rather than asked for.\n    "))?; __attrs_1421.dict_set(Value::from("__defaults__"), Value::None)?; let __kwdefaults_1422 = Value::dict(); __attrs_1421.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_1418 = Frame::module(frame.globals.clone()); let mut __function_1420 = NativeFunction::qualified_with_origin("_asks_to_hear_it_again".into(), "_asks_to_hear_it_again".into(), "bot.modules.memory_store".into(), __attrs_1421, pyrt::object::FunctionOrigin { span: pyrt::runtime::SourceSpan { file: "bot/modules/memory_store.py", first: 4361, last: 4371, qualname: "_asks_to_hear_it_again" }, closure: __closure_1418.clone(), freevars: vec![] }, move |rt, args| __py_80::_asks_to_hear_it_again(rt, __closure_1418.clone(), &__signature_1419, args)); __function_1420 })?;
